urlset:
{# 首页：最高优先级，每日更新 #}

  {{ host }}/
  daily
  1.0

{# 归档页 #}

  {{ host }}{% url 'archive' %}
  weekly
  0.7

{# 分类页 #}
{% for c in categories %}

  {{ host }}{% url 'category_detail' c.pk %}
  weekly
  0.6

{% endfor %}
{# 标签页 #}
{% for t in tags %}

  {{ host }}{% url 'tag_detail' t.pk %}
  weekly
  0.5

{% endfor %}
{# 文章详情页：lastmod 用文章更新时间 #}
{% for a in articles %}

  {{ host }}{% url 'article_detail' a.pk %}
  {{ a.updated_at|date:"Y-m-d" }}
  weekly
  0.8

{% endfor %}
